54	static void usage(FAR const char *prog)
55	{
56	  printf("Usage:\n");
57	  printf("  %s scan [-a min-max]     # fixed %d baud\n", prog,
58	         CONFIG_VG_DISCOVER_BAUD);
59	  printf("  %s probe -a <addr> [-t 3|4|both]\n", prog);
60	  printf("  %s dump [-o path]\n", prog);
61	  printf("  %s test-read -a <addr> -r <reg> [-c qty]\n", prog);
62	  printf("  %s apply [--confirm]\n", prog);
63	}
64	
65	static int parse_opt_u8(int argc, char *argv[], int start,
66	                        FAR const char *flag, FAR uint8_t *out)
67	{
68	  int i;
69	
70	  for (i = start; i < argc - 1; i++)
71	    {
72	      if (strcmp(argv[i], flag) == 0)
73	        {
74	          long v = strtol(argv[i + 1], NULL, 0);
75	
76	          if (v >= 1 && v <= 247)
77	            {
78	              *out = (uint8_t)v;
79	              return 0;
80	            }
81	
82	          return -EINVAL;
83	        }
84	    }
85	
86	  return -ENOENT;
87	}
88	
89	static int parse_opt_u16(int argc, char *argv[], int start,
90	                         FAR const char *flag, FAR uint16_t *out)
91	{
92	  int i;
93	
94	  for (i = start; i < argc - 1; i++)
95	    {
96	      if (strcmp(argv[i], flag) == 0)
97	        {
98	          long v = strtol(argv[i + 1], NULL, 0);
99	
100	          if (v >= 0 && v <= 65535)
101	            {
102	              *out = (uint16_t)v;
103	              return 0;
104	            }
105	
106	          return -EINVAL;
107	        }
108	    }
109	
110	  return -ENOENT;
111	}
