113	int main(int argc, char *argv[])
114	{
115	  FAR struct vg_discover_summary *sum = vg_discover_state();
116	  FAR const char *dev = CONFIG_VG_DISCOVER_DEVPATH;
117	  int ret;
118	  int i;
119	
120	  if (argc < 2)
121	    {
122	      usage(argv[0]);
123	      return 1;
124	    }
125	
126	  vg_discover_reset(sum);
127	
128	  if (strcmp(argv[1], "scan") == 0)
129	    {
130	      int amin = CONFIG_VG_DISCOVER_ADDR_MIN;
131	      int amax = CONFIG_VG_DISCOVER_ADDR_MAX;
132	
133	      if (argc >= 4 && strcmp(argv[2], "-a") == 0)
134	        {
135	          if (!vg_discover_parse_addr_range(argv[3], &amin, &amax))
136	            {
137	              fprintf(stderr, "vgdiscover: bad -a range\n");
138	              return 1;
139	            }
140	        }
141	
142	      printf("vgdiscover: scan %s @%d addr %d..%d\n",
143	             dev, CONFIG_VG_DISCOVER_BAUD, amin, amax);
144	
145	      ret = vg_bus_scan(sum, dev, CONFIG_VG_DISCOVER_BAUD,
146	                        amin, amax, CONFIG_VG_DISCOVER_INTER_MS);
147	      if (ret < 0)
148	        {
149	          fprintf(stderr, "vgdiscover: scan failed %d\n", ret);
150	          return 1;
151	        }
152	
153	      printf("vgdiscover: found %d slave(s):\n", sum->n_hits);
154	      for (i = 0; i < sum->n_hits; i++)
155	        {
156	          printf("  addr=%u\n", (unsigned)sum->hits[i].addr);
157	        }
158	
159	      if (vg_discover_state_save(sum, NULL) != 0)
160	        {
161	          fprintf(stderr, "vgdiscover: state save failed\n");
162	        }
163	
164	      return (sum->n_hits > 0) ? 0 : 1;
165	    }
166	
167	  if (strcmp(argv[1], "probe") == 0)
168	    {
169	      uint8_t addr = 0;
170	      int fc = 0;
171	      int ai;
172	
173	      for (ai = 2; ai < argc; ai++)
174	        {
175	          if (strcmp(argv[ai], "-t") == 0 && ai + 1 < argc)
176	            {
177	              ai++;
178	              if (strcmp(argv[ai], "3") == 0)
179	                {
180	                  fc = 3;
181	                }
182	              else if (strcmp(argv[ai], "4") == 0)
183	                {
184	                  fc = 4;
185	                }
186	              else if (strcmp(argv[ai], "both") == 0)
187	                {
188	                  fc = 0;
189	                }
190	              else
191	                {
192	                  fprintf(stderr, "vgdiscover: -t must be 3, 4, or both\n");
193	                  return 1;
194	                }
195	            }
196	        }
197	
198	      if (parse_opt_u8(argc, argv, 2, "-a", &addr) != 0)
199	        {
200	          fprintf(stderr, "vgdiscover: probe requires -a <addr>\n");
201	          return 1;
202	        }
203	
204	      (void)vg_discover_state_load(sum, NULL);
205	      sum->n_blocks = 0;
206	
207	      ret = vg_reg_probe_slave(sum, dev, CONFIG_VG_DISCOVER_BAUD,
208	                               addr, fc, CONFIG_VG_DISCOVER_REG_MAX);
209	      if (ret < 0)
210	        {
211	          fprintf(stderr, "vgdiscover: probe failed %d\n", ret);
212	          return 1;
213	        }
214	
215	      printf("vgdiscover: probe addr=%u blocks=%d\n",
216	             (unsigned)addr, sum->n_blocks);
217	      for (i = 0; i < sum->n_blocks; i++)
218	        {
219	          FAR struct vg_reg_block *b = &sum->blocks[i];
220	
221	          printf("  fc=%u start=%u count=%u sample[0]=%u sample[1]=%u\n",
222	                 (unsigned)b->fc, (unsigned)b->start, (unsigned)b->count,
223	                 (unsigned)b->sample[0], (unsigned)b->sample[1]);
224	        }
225	
226	      (void)vg_discover_state_save(sum, NULL);
227	      return (sum->n_blocks > 0) ? 0 : 1;
228	    }
229	
230	  if (strcmp(argv[1], "dump") == 0)
231	    {
232	      FAR const char *out = CONFIG_VG_DISCOVER_CANDIDATE_PATH;
233	
234	      if (argc >= 4 && strcmp(argv[2], "-o") == 0)
235	        {
236	          out = argv[3];
237	        }
238	
239	      if (vg_discover_state_load(sum, NULL) != 0)
240	        {
241	          fprintf(stderr, "vgdiscover: no saved state — run scan/probe first\n");
242	          return 1;
243	        }
244	
245	      vg_point_table_infer(sum);
246	      ret = vg_point_table_write_candidate(sum, out);
247	      if (ret != 0)
248	        {
249	          fprintf(stderr, "vgdiscover: dump failed %d\n", ret);
250	          return 1;
251	        }
252	
253	      printf("vgdiscover: wrote %d points → %s\n", sum->n_points, out);
254	      (void)vg_discover_state_save(sum, NULL);
255	      return 0;
256	    }
257	
258	  if (strcmp(argv[1], "test-read") == 0)
259	    {
260	      uint8_t addr = 0;
261	      uint16_t reg = 0;
262	      uint16_t qty = 2;
263	      uint16_t vals[16];
264	      unsigned int j;
265	
266	      if (parse_opt_u8(argc, argv, 2, "-a", &addr) != 0)
267	        {
268	          fprintf(stderr, "vgdiscover: test-read requires -a <addr>\n");
269	          return 1;
270	        }
271	
272	      (void)parse_opt_u16(argc, argv, 2, "-r", &reg);
273	      if (parse_opt_u16(argc, argv, 2, "-c", &qty) != 0)
274	        {
275	          qty = 2;
276	        }
277	
278	      if (qty > 16)
279	        {
280	          qty = 16;
281	        }
282	
283	      ret = vg_discover_test_read(dev, CONFIG_VG_DISCOVER_BAUD,
284	                                  addr, reg, qty, vals);
285	      if (ret != 0)
286	        {
287	          fprintf(stderr, "vgdiscover: test-read failed %d\n", ret);
288	          return 1;
289	        }
290	
291	      printf("vgdiscover: addr=%u reg=%u:", (unsigned)addr, (unsigned)reg);
292	      for (j = 0; j < qty; j++)
293	        {
294	          float s = vg_discover_decode_int16_scaled((int16_t)vals[j], 0.1f);
295	
296	          printf(" [%u]=%u (%.1f)", (unsigned)(reg + j),
297	                 (unsigned)vals[j], (double)s);
298	        }
299	
300	      printf("\n");
301	      return 0;
302	    }
303	
304	  if (strcmp(argv[1], "apply") == 0)
305	    {
306	      bool confirm = false;
307	
308	      for (i = 2; i < argc; i++)
309	        {
310	          if (strcmp(argv[i], "--confirm") == 0)
311	            {
312	              confirm = true;
313	            }
314	        }
315	
316	      if (vg_discover_state_load(sum, NULL) != 0)
317	        {
318	          fprintf(stderr, "vgdiscover: no saved state — run dump first\n");
319	          return 1;
320	        }
321	
322	      if (sum->n_points == 0)
323	        {
324	          vg_point_table_infer(sum);
325	        }
326	
327	      ret = vg_point_table_apply(sum, CONFIG_VG_DISCOVER_POINTS_PATH,
328	                                 CONFIG_VG_CONFIG_BASEDIR, confirm);
329	      return (ret == 0) ? 0 : 1;
330	    }
331	
332	  usage(argv[0]);
333	  return 1;
334	}
