21	#endif
22	
23	#define VG_DISC_READ_TO_MS   500
24	/* Match the alarm reader (VG_ALARM_BYTE_TO_MS): 20 ms drops whole frames
25	 * whenever the simulator gaps between bytes, producing fake fail samples. */
26	#define VG_DISC_BYTE_TO_MS   50
27	#define VG_DISC_MAX_REGS     16
28	#define VG_DISC_SCAN_TO_MS   400
29	#define VG_DISC_RETRY_INTER_MS 100
30	
31	struct vg_disc_nmbs
32	{
33	  struct vg_modbus_port_s port;
34	  nmbs_t                  nmbs;
35	  bool                    ready;
36	};
37	
38	static int vg_disc_nmbs_open(FAR struct vg_disc_nmbs *s, FAR const char *dev)
39	{
40	  nmbs_platform_conf pc;
41	  nmbs_error err;
42	
43	  if (s == NULL || dev == NULL)
44	    {
45	      return -EINVAL;
46	    }
47	
48	  memset(s, 0, sizeof(*s));
49	  s->port.fd = -1;
50	
51	  if (vg_modbus_port_open(&s->port, dev) < 0)
52	    {
53	      return -errno;
54	    }
55	
56	  vg_modbus_port_bind(&s->port, &pc);
57	  err = nmbs_client_create(&s->nmbs, &pc);
58	  if (err != NMBS_ERROR_NONE)
59	    {
60	      vg_modbus_port_close(&s->port);
61	      return -EIO;
62	    }
63	
64	  nmbs_set_read_timeout(&s->nmbs, VG_DISC_READ_TO_MS);
65	  nmbs_set_byte_timeout(&s->nmbs, VG_DISC_BYTE_TO_MS);
66	  s->ready = true;
67	  return 0;
68	}
69	
70	static void vg_disc_nmbs_close(FAR struct vg_disc_nmbs *s)
71	{
72	  if (s == NULL || !s->ready)
73	    {
74	      return;
75	    }
76	
77	  vg_modbus_port_close(&s->port);
78	  s->ready = false;
79	}
80	
81	static nmbs_error vg_disc_read_holding(FAR struct vg_disc_nmbs *s,
82	                                       uint8_t addr, uint16_t start,
83	                                       uint16_t qty, FAR uint16_t *regs)
84	{
85	  if (!s->ready || qty == 0 || qty > VG_DISC_MAX_REGS)
86	    {
87	      return NMBS_ERROR_INVALID_ARGUMENT;
88	    }
89	
90	  nmbs_set_destination_rtu_address(&s->nmbs, addr);
91	  return nmbs_read_holding_registers(&s->nmbs, start, qty, regs);
92	}
93	
94	static nmbs_error vg_disc_read_input(FAR struct vg_disc_nmbs *s,
95	                                     uint8_t addr, uint16_t start,
96	                                     uint16_t qty, FAR uint16_t *regs)
97	{
98	  if (!s->ready || qty == 0 || qty > VG_DISC_MAX_REGS)
99	    {
100	      return NMBS_ERROR_INVALID_ARGUMENT;
101	    }
102	
103	  nmbs_set_destination_rtu_address(&s->nmbs, addr);
104	  return nmbs_read_input_registers(&s->nmbs, start, qty, regs);
105	}
