107	/* Probe tries qty=16 first; fall back to 2/1 for narrow mock slaves. */
108	static nmbs_error vg_disc_probe_read_holding(FAR struct vg_disc_nmbs *s,
109	                                             uint8_t addr, uint16_t start,
110	                                             FAR uint16_t *regs,
111	                                             FAR uint16_t *qty_out)
112	{
113	  static const uint16_t try_qty[] =
114	    {
115	      VG_DISCOVER_PROBE_QTY, 2, 1
116	    };
117	  int i;
118	
119	  for (i = 0; i < (int)(sizeof(try_qty) / sizeof(try_qty[0])); i++)
120	    {
121	      nmbs_error err;
122	
123	      memset(regs, 0, sizeof(uint16_t) * try_qty[i]);
124	      err = vg_disc_read_holding(s, addr, start, try_qty[i], regs);
125	      if (err == NMBS_ERROR_NONE)
126	        {
127	          if (qty_out != NULL)
128	            {
129	              *qty_out = try_qty[i];
130	            }
131	
132	          return err;
133	        }
134	    }
135	
136	  if (qty_out != NULL)
137	    {
138	      *qty_out = 0;
139	    }
140	
141	  return NMBS_ERROR_TRANSPORT;
142	}
