144	/* Address scan: any FC03 response (incl. exception) proves the slave is alive.
145	 * velaguard.mthings: 32 slaves; addr=2 rejects reg0 with exception 02 then OK @reg2.
146	 */
147	static bool vg_disc_err_means_alive(nmbs_error err)
148	{
149	  return err == NMBS_ERROR_NONE ||
150	         err == NMBS_EXCEPTION_ILLEGAL_FUNCTION ||
151	         err == NMBS_EXCEPTION_ILLEGAL_DATA_ADDRESS ||
152	         err == NMBS_EXCEPTION_ILLEGAL_DATA_VALUE ||
153	         err == NMBS_EXCEPTION_SERVER_DEVICE_FAILURE;
154	}
