156	static nmbs_error vg_disc_scan_probe_holding(FAR struct vg_disc_nmbs *s,
157	                                             uint8_t addr,
158	                                             FAR uint16_t *regs,
159	                                             FAR uint16_t *start_out)
160	{
161	  static const uint16_t try_start[] = { 0, 2, 1 };
162	  static const uint16_t try_qty[] = { 1, 2 };
163	  int i;
164	  int j;
165	
166	  nmbs_set_read_timeout(&s->nmbs, VG_DISC_SCAN_TO_MS);
167	
168	  for(i = 0; i < (int)(sizeof(try_start) / sizeof(try_start[0])); i++)
169	    {
170	      for(j = 0; j < (int)(sizeof(try_qty) / sizeof(try_qty[0])); j++)
171	        {
172	          nmbs_error err;
173	
174	          err = vg_disc_read_holding(s, addr, try_start[i], try_qty[j], regs);
175	          if(vg_disc_err_means_alive(err))
176	            {
177	              if(start_out != NULL)
178	                {
179	                  *start_out = try_start[i];
180	                }
181	
182	              nmbs_set_read_timeout(&s->nmbs, VG_DISC_READ_TO_MS);
183	              return NMBS_ERROR_NONE;
184	            }
185	        }
186	    }
187	
188	  if(start_out != NULL)
189	    {
190	      *start_out = 0;
191	    }
192	
193	  nmbs_set_read_timeout(&s->nmbs, VG_DISC_READ_TO_MS);
194	  return NMBS_ERROR_TRANSPORT;
195	}
