259	int vg_discover_poll_holding(FAR const char *devpath, int baud,
260	                            const uint8_t *addr, const uint16_t *reg,
261	                            uint16_t *raw, uint8_t *ok_out, int n,
262	                            int inter_ms)
263	{
264	  struct vg_disc_nmbs s;
265	  int i;
266	
267	  (void)baud;
268	
269	  if (devpath == NULL || addr == NULL || reg == NULL ||
270	      raw == NULL || ok_out == NULL || n <= 0)
271	    {
272	      return -EINVAL;
273	    }
274	
275	  if (vg_disc_nmbs_open(&s, devpath) != 0)
276	    {
277	      return -errno;
278	    }
279	
280	  for (i = 0; i < n; i++)
281	    {
282	      nmbs_error err;
283	
284	      raw[i] = 0;
285	      ok_out[i] = 0;
286	      if (addr[i] == 0)
287	        {
288	          continue;
289	        }
290	
291	      err = vg_disc_read_holding(&s, addr[i], reg[i], 1, &raw[i]);
292	      if (err == NMBS_ERROR_NONE)
293	        {
294	          ok_out[i] = 1;
295	        }
296	
297	      if (inter_ms > 0 && i + 1 < n)
298	        {
299	          usleep((useconds_t)inter_ms * 1000);
300	        }
301	    }
302	
303	  vg_disc_nmbs_close(&s);
304	  return 0;
