307	int vg_discover_poll_points(FAR const char *devpath, int baud,
308	                            FAR const struct vg_point_entry *pts, int n,
309	                            FAR uint16_t *raw, FAR uint8_t *ok_out,
310	                            int inter_ms)
311	{
312	  struct vg_disc_nmbs s;
313	  int i;
314	
315	  (void)baud;
316	
317	  if (devpath == NULL || pts == NULL || raw == NULL ||
318	      ok_out == NULL || n <= 0)
319	    {
320	      return -EINVAL;
321	    }
322	
323	  if (vg_disc_nmbs_open(&s, devpath) != 0)
324	    {
325	      return -errno;
326	    }
327	
328	  for (i = 0; i < n; i++)
329	    {
330	      nmbs_error err;
331	      int attempt;
332	      uint16_t qty = pts[i].qty;
333	      uint16_t tmp[VG_DISC_MAX_REGS];
334	
335	      raw[i] = 0;
336	      ok_out[i] = 0;
337	      if (pts[i].addr == 0)
338	        {
339	          continue;
340	        }
341	
342	      if (qty < 1)
343	        {
344	          qty = 1;
345	        }
346	
347	      if (qty > VG_DISC_MAX_REGS)
348	        {
349	          qty = VG_DISC_MAX_REGS;
350	        }
351	
352	      /* One immediate retry: a single missed frame must not count as an
353	       * offline sample in the HMI's sliding-window detection. */
354	      err = NMBS_ERROR_TRANSPORT;
355	#ifdef CONFIG_VG_FRAME_STATS
356	      {
357	        struct timespec t0;
358	        struct timespec t1;
359	        uint32_t lat_ms = 0;
360	        enum vg_fs_result fs = VG_FS_OTHER;
361	
362	        clock_gettime(CLOCK_MONOTONIC, &t0);
363	#endif
364	      for (attempt = 0; attempt < 2; attempt++)
365	        {
366	          if (attempt > 0)
367	            {
368	              usleep((useconds_t)VG_DISC_RETRY_INTER_MS * 1000);
369	            }
370	
371	          if (pts[i].fc == 4)
372	            {
373	              err = vg_disc_read_input(&s, pts[i].addr, pts[i].reg, qty, tmp);
374	            }
375	          else
376	            {
377	              err = vg_disc_read_holding(&s, pts[i].addr, pts[i].reg, qty,
378	                                         tmp);
379	            }
380	
381	          if (err == NMBS_ERROR_NONE)
382	            {
383	              break;
384	            }
385	        }
386	
387	#ifdef CONFIG_VG_FRAME_STATS
388	        clock_gettime(CLOCK_MONOTONIC, &t1);
389	        if (t1.tv_sec > t0.tv_sec ||
390	            (t1.tv_sec == t0.tv_sec && t1.tv_nsec >= t0.tv_nsec))
391	          {
392	            lat_ms = (uint32_t)((t1.tv_sec - t0.tv_sec) * 1000L +
393	                                (t1.tv_nsec - t0.tv_nsec) / 1000000L);
394	          }
395	
396	        if (err == NMBS_ERROR_NONE)
397	          {
398	            fs = VG_FS_OK;
399	          }
400	        else if (err == NMBS_ERROR_CRC)
401	          {
402	            fs = VG_FS_CRC;
403	          }
404	        else if (err == NMBS_ERROR_TIMEOUT)
405	          {
406	            fs = VG_FS_TIMEOUT;
407	          }
408	
409	        (void)vg_fs_record(pts[i].addr, fs,
410	                           (err == NMBS_ERROR_NONE) ? lat_ms : 0);
411	      }
412	#endif
413	
414	      if (err == NMBS_ERROR_NONE)
415	        {
416	          raw[i] = tmp[0];
417	          ok_out[i] = 1;
418	        }
419	
420	      if (inter_ms > 0 && i + 1 < n)
421	        {
422	          usleep((useconds_t)inter_ms * 1000);
423	        }
424	    }
425	
426	  vg_disc_nmbs_close(&s);
427	  return 0;
428	}
