430	static bool vg_disc_hit_has(FAR const struct vg_discover_summary *sum,
431	                            uint8_t addr)
432	{
433	  int i;
434	
435	  if(sum == NULL)
436	    {
437	      return false;
438	    }
439	
440	  for(i = 0; i < sum->n_hits; i++)
441	    {
442	      if(sum->hits[i].alive && sum->hits[i].addr == addr)
443	        {
444	          return true;
445	        }
446	    }
447	
448	  return false;
