451	static int vg_bus_scan_pass(FAR struct vg_disc_nmbs *s,
452	                            FAR struct vg_discover_summary *sum,
453	                            int addr_min, int addr_max, int inter_ms,
454	                            bool skip_known)
455	{
456	  int addr;
457	  int n = 0;
458	
459	  for(addr = addr_min; addr <= addr_max; addr++)
460	    {
461	      uint16_t regs[2];
462	      uint16_t probe_start;
463	      nmbs_error err;
464	
465	      if(sum->n_hits >= VG_DISCOVER_MAX_SLAVES)
466	        {
467	          break;
468	        }
469	
470	      if(skip_known && vg_disc_hit_has(sum, (uint8_t)addr))
471	        {
472	          continue;
473	        }
474	
475	      sum->scan_addr = addr;
476	      err = vg_disc_scan_probe_holding(s, (uint8_t)addr, regs, &probe_start);
477	      if(err == NMBS_ERROR_NONE)
478	        {
479	          sum->hits[sum->n_hits].addr      = (uint8_t)addr;
480	          sum->hits[sum->n_hits].alive     = true;
481	          sum->hits[sum->n_hits].probe_reg = probe_start;
482	          sum->n_hits++;
483	          n++;
484	        }
485	
486	      if(inter_ms > 0)
487	        {
488	          usleep((useconds_t)inter_ms * 1000);
489	        }
490	    }
491	
492	  return n;
493	}
