495	int vg_bus_scan(FAR struct vg_discover_summary *sum,
496	                FAR const char *devpath,
497	                int baud, int addr_min, int addr_max, int inter_ms)
498	{
499	  struct vg_disc_nmbs s;
500	  int n = 0;
501	  int retry_inter;
502	
503	  if (sum == NULL || devpath == NULL || addr_min < 1 || addr_max > 247 ||
504	      addr_min > addr_max)
505	    {
506	      return -EINVAL;
507	    }
508	
509	  if (vg_disc_nmbs_open(&s, devpath) != 0)
510	    {
511	      return -errno;
512	    }
513	
514	  sum->baud = baud;
515	  snprintf(sum->devpath, sizeof(sum->devpath), "%s", devpath);
516	  sum->n_hits = 0;
517	  sum->scan_addr_min = addr_min;
518	  sum->scan_addr_max = addr_max;
519	  sum->scan_addr = 0;
520	
521	  n = vg_bus_scan_pass(&s, sum, addr_min, addr_max, inter_ms, false);
522	
523	  retry_inter = inter_ms > 0 ? inter_ms : VG_DISC_RETRY_INTER_MS;
524	  if(retry_inter < VG_DISC_RETRY_INTER_MS)
525	    {
526	      retry_inter = VG_DISC_RETRY_INTER_MS;
527	    }
528	
529	  if(sum->n_hits < (addr_max - addr_min + 1))
530	    {
531	      n += vg_bus_scan_pass(&s, sum, addr_min, addr_max, retry_inter, true);
532	    }
533	
534	  sum->scan_addr = 0;
535	  vg_disc_nmbs_close(&s);
536	  return n;
537	}
