539	int vg_reg_probe_slave(FAR struct vg_discover_summary *sum,
540	                       FAR const char *devpath, int baud,
541	                       uint8_t addr, int fc_filter, int reg_max)
542	{
543	  struct vg_disc_nmbs s;
544	  int fail_streak = 0;
545	  uint16_t start;
546	
547	  if (sum == NULL || devpath == NULL || addr == 0)
548	    {
549	      return -EINVAL;
550	    }
551	
552	  if (reg_max <= 0)
553	    {
554	      reg_max = 120;
555	    }
556	
557	  if (vg_disc_nmbs_open(&s, devpath) != 0)
558	    {
559	      return -errno;
560	    }
561	
562	  sum->baud = baud;
563	  snprintf(sum->devpath, sizeof(sum->devpath), "%s", devpath);
564	
565	  for (start = 0; start < (uint16_t)reg_max && fail_streak < 3; )
566	    {
567	      uint16_t regs[VG_DISCOVER_PROBE_QTY];
568	      uint16_t got_qty = 0;
569	      nmbs_error err;
570	      int do_holding = (fc_filter == 0 || fc_filter == 3);
571	      int do_input   = (fc_filter == 0 || fc_filter == 4);
572	
573	      if (sum->n_blocks >= VG_DISCOVER_MAX_BLOCKS)
574	        {
575	          break;
576	        }
577	
578	      memset(regs, 0, sizeof(regs));
579	      err = NMBS_ERROR_TRANSPORT;
580	
581	      if (do_holding)
582	        {
583	          err = vg_disc_probe_read_holding(&s, addr, start, regs, &got_qty);
584	          if (err == NMBS_ERROR_NONE)
585	            {
586	              FAR struct vg_reg_block *b = &sum->blocks[sum->n_blocks];
587	
588	              b->addr   = addr;
589	              b->fc     = 3;
590	              b->start  = start;
591	              b->count  = got_qty;
592	              memcpy(b->sample, regs, sizeof(b->sample));
593	              sum->n_blocks++;
594	              fail_streak = 0;
595	              start += VG_DISCOVER_BLOCK_STEP;
596	              continue;
597	            }
598	        }
599	
600	      if (do_input)
601	        {
602	          err = vg_disc_probe_read_input(&s, addr, start, regs, &got_qty);
603	          if (err == NMBS_ERROR_NONE)
604	            {
605	              FAR struct vg_reg_block *b = &sum->blocks[sum->n_blocks];
606	
607	              b->addr   = addr;
608	              b->fc     = 4;
609	              b->start  = start;
610	              b->count  = got_qty;
611	              memcpy(b->sample, regs, sizeof(b->sample));
612	              sum->n_blocks++;
613	              fail_streak = 0;
614	              start += VG_DISCOVER_BLOCK_STEP;
615	              continue;
616	            }
617	        }
618	
619	      fail_streak++;
620	      start += VG_DISCOVER_BLOCK_STEP;
621	    }
622	
623	  vg_disc_nmbs_close(&s);
624	  return sum->n_blocks;
625	}
