36	static FAR const char *vgscan_pick_dev(void)
37	{
38	  static const char *const candidates[] =
39	  {
40	    CONFIG_VG_HMI_RS485_DEVPATH,
41	    "/dev/rs485",
42	    "/dev/ttyS1",
43	    "/dev/ttyS2",
44	    NULL
45	  };
46	  int i;
47	
48	  for(i = 0; candidates[i] != NULL; i++)
49	    {
50	      if(access(candidates[i], R_OK | W_OK) == 0)
51	        {
52	          return candidates[i];
53	        }
54	    }
55	
56	  return CONFIG_VG_HMI_RS485_DEVPATH;
57	}
