59	int main(int argc, FAR char *argv[])
60	{
61	  FAR struct vg_discover_summary *sum = vg_discover_state();
62	  FAR const char *dev;
63	  int amin = CONFIG_VG_HMI_DISCOVER_ADDR_MIN;
64	  int amax = CONFIG_VG_HMI_DISCOVER_ADDR_MAX;
65	  int inter = CONFIG_VG_HMI_DISCOVER_INTER_MS;
66	  int ret;
67	  int i;
68	
69	  if(argc >= 3 && strcmp(argv[1], "-a") == 0)
70	    {
71	      if(!vg_discover_parse_addr_range(argv[2], &amin, &amax))
72	        {
73	          fprintf(stderr, "vgscan: bad -a range\n");
74	          return 1;
75	        }
76	    }
77	
78	  vg_discover_reset(sum);
79	  dev = vgscan_pick_dev();
80	
81	  printf("vgscan: %s @%d addr %d..%d inter=%dms\n",
82	         dev, CONFIG_VG_HMI_DISCOVER_BAUD, amin, amax, inter);
83	
84	  ret = vg_bus_scan(sum, dev, CONFIG_VG_HMI_DISCOVER_BAUD, amin, amax, inter);
85	  if(ret < 0)
86	    {
87	      fprintf(stderr, "vgscan: failed %d (errno=%d)\n", ret, errno);
88	      return 1;
89	    }
90	
91	  printf("vgscan: found %d/%d slave(s):\n", sum->n_hits,
92	         amax - amin + 1);
93	  for(i = 0; i < sum->n_hits; i++)
94	    {
95	      printf("  addr=%u reg=%u\n",
96	             (unsigned)sum->hits[i].addr,
97	             (unsigned)sum->hits[i].probe_reg);
98	    }
99	
100	  return (sum->n_hits >= (amax - amin + 1)) ? 0 : 1;
101	}
