74	bool vg_discover_parse_addr_range(FAR const char *spec,
75	                                    int *min_out, int *max_out)
76	{
77	  int a;
78	  int b;
79	
80	  if (spec == NULL || min_out == NULL || max_out == NULL)
81	    {
82	      return false;
83	    }
84	
85	  if (strchr(spec, '-') != NULL)
86	    {
87	      if (sscanf(spec, "%d-%d", &a, &b) != 2)
88	        {
89	          return false;
90	        }
91	    }
92	  else
93	    {
94	      a = b = (int)strtol(spec, NULL, 0);
95	    }
96	
97	  if (a < 1 || b > 247 || a > b)
98	    {
99	      return false;
100	    }
101	
102	  *min_out = a;
103	  *max_out = b;
104	  return true;
105	}
