107	static int mkdir_p(FAR const char *path)
108	{
109	  char tmp[128];
110	  char *p;
111	  size_t len;
112	
113	  if (path == NULL)
114	    {
115	      return -EINVAL;
116	    }
117	
118	  snprintf(tmp, sizeof(tmp), "%s", path);
119	  len = strlen(tmp);
120	  if (len == 0)
121	    {
122	      return -EINVAL;
123	    }
124	
125	  for (p = tmp + 1; *p != '\0'; p++)
126	    {
127	      if (*p == '/')
128	        {
129	          *p = '\0';
130	          (void)mkdir(tmp, 0755);
131	          *p = '/';
132	        }
133	    }
134	
135	  /* An existing leaf directory is success, not failure.  Callers use the
136	   * return value to tell "cannot create" apart from "already there"; the
137	   * raw mkdir() result cannot express that.
138	   */
139	
140	  if (mkdir(tmp, 0755) != 0 && errno != EEXIST)
141	    {
142	      return -errno;
143	    }
144	
145	  return 0;
146	}
