148	static int mkdir_parent(FAR const char *filepath)
149	{
150	  char tmp[160];
151	  char *slash;
152	
153	  if (filepath == NULL || filepath[0] == '\0')
154	    {
155	      return -EINVAL;
156	    }
157	
158	  snprintf(tmp, sizeof(tmp), "%s", filepath);
159	  slash = strrchr(tmp, '/');
160	  if (slash == NULL || slash == tmp)
161	    {
162	      return 0;
163	    }
164	
165	  *slash = '\0';
166	  return mkdir_p(tmp);
167	}
