230	static void add_point(FAR struct vg_discover_summary *sum,
231	                      uint8_t addr, uint8_t fc, uint16_t reg,
232	                      FAR const char *id, FAR const char *dtype,
233	                      float scale, FAR const char *unit)
234	{
235	  FAR struct vg_point_entry *p;
236	
237	  if (sum->n_points >= VG_DISCOVER_MAX_POINTS)
238	    {
239	      return;
240	    }
241	
242	  p = &sum->points[sum->n_points++];
243	  memset(p, 0, sizeof(*p));
244	  p->addr = addr;
245	  p->fc   = fc;
246	  p->reg  = reg;
247	  p->qty  = 1;
248	  snprintf(p->id, sizeof(p->id), "%s", id);
249	  snprintf(p->name, sizeof(p->name), "%s", id);
250	  snprintf(p->dtype, sizeof(p->dtype), "%s", dtype);
251	  p->scale = scale;
252	  snprintf(p->unit, sizeof(p->unit), "%s", unit);
253	  p->fail_n = 3;
254	}
