256	int vg_point_table_infer(FAR struct vg_discover_summary *sum)
257	{
258	  int i;
259	
260	  if (sum == NULL)
261	    {
262	      return -EINVAL;
263	    }
264	
265	  sum->n_points = 0;
266	
267	  for (i = 0; i < sum->n_blocks; i++)
268	    {
269	      FAR struct vg_reg_block *b = &sum->blocks[i];
270	      int tag_idx = 0;
271	
272	      if (b->count == 0)
273	        {
274	          continue;
275	        }
276	
277	      for (tag_idx = 0; tag_idx < (int)b->count && tag_idx < 4; tag_idx++)
278	        {
279	          char id[VG_POINT_ID_MAX];
280	          float scaled;
281	
282	          scaled = vg_discover_decode_int16_scaled((int16_t)b->sample[tag_idx],
283	                                                   0.1f);
284	          snprintf(id, sizeof(id), "s%u_r%u_%d",
285	                   (unsigned)b->addr,
286	                   (unsigned)(b->start + (uint16_t)tag_idx), tag_idx);
287	
288	          if (scaled >= -50.0f && scaled <= 120.0f)
289	            {
290	              add_point(sum, b->addr, b->fc,
291	                        (uint16_t)(b->start + (uint16_t)tag_idx),
292	                        id, "int16", 0.1f, (tag_idx == 0) ? "C" : "%RH");
293	            }
294	          else
295	            {
296	              add_point(sum, b->addr, b->fc,
297	                        (uint16_t)(b->start + (uint16_t)tag_idx),
298	                        id, "uint16", 1.0f, "");
299	            }
300	        }
301	    }
302	
303	  return sum->n_points;
304	}
