306	int vg_point_table_write_candidate(FAR const struct vg_discover_summary *sum,
307	                                     FAR const char *path)
308	{
309	  FILE *fp;
310	  int i;
311	  int ret;
312	  FAR const char *out = path;
313	
314	  if (sum == NULL || out == NULL)
315	    {
316	      return -EINVAL;
317	    }
318	
319	  /* Create the parent of the path we were actually handed.  The candidate
320	   * and the committed table live in different directories, so a hard-wired
321	   * path here silently made one of them depend on board bring-up.
322	   */
323	
324	  ret = mkdir_parent(out);
325	  if (ret != 0)
326	    {
327	      return ret;
328	    }
329	
330	  fp = fopen(out, "w");
331	  if (fp == NULL)
332	    {
333	      return -errno;
334	    }
335	
336	  fprintf(fp,
337	          "{\"schema_version\":1,\"bus\":{\"device\":\"%s\",\"baud\":%d},"
338	          "\"hits\":[",
339	          sum->devpath, sum->baud);
340	
341	  for (i = 0; i < sum->n_hits; i++)
342	    {
343	      fprintf(fp, "%s%u", (i > 0) ? "," : "",
344	              (unsigned)sum->hits[i].addr);
345	    }
346	
347	  fprintf(fp, "],\"points\":[");
348	
349	  for (i = 0; i < sum->n_points; i++)
350	    {
351	      FAR const struct vg_point_entry *p = &sum->points[i];
352	
353	      fprintf(fp,
354	              "%s{\"id\":\"%s\",\"name\":\"%s\",\"addr\":%u,\"fc\":%u,\"reg\":%u,"
355	              "\"qty\":%u,\"dtype\":\"%s\",\"scale\":%.3f,\"unit\":\"%s\"",
356	              (i > 0) ? "," : "",
357	              p->id, p->name[0] ? p->name : p->id,
358	              (unsigned)p->addr, (unsigned)p->fc,
359	              (unsigned)p->reg, (unsigned)p->qty,
360	              p->dtype, (double)p->scale, p->unit);
361	      if (p->cmp[0] != '\0')
362	        {
363	          fprintf(fp, ",\"cmp\":\"%s\"", p->cmp);
364	        }
365	
366	      if (p->has_warn)
367	        {
368	          fprintf(fp, ",\"warn\":%.6g", (double)p->warn);
369	        }
370	
371	      if (p->has_crit)
372	        {
373	          fprintf(fp, ",\"crit\":%.6g", (double)p->crit);
374	        }
375	
376	      fprintf(fp, ",\"fail_n\":%u}",
377	              (unsigned)((p->fail_n >= 1) ? p->fail_n : 3));
378	    }
379	
380	  fprintf(fp, "]}\n");
381	
382	  /* A full or dying medium used to report success, leaving a truncated
383	   * table that later read back as zero points.  Drop the half-written file
384	   * instead of publishing it.
385	   */
386	
387	  if (ferror(fp) != 0)
388	    {
389	      fclose(fp);
390	      unlink(out);
391	      return -EIO;
392	    }
393	
394	  if (fclose(fp) != 0)
395	    {
396	      unlink(out);
397	      return -EIO;
398	    }
399	
400	  return 0;
401	}
