455	static int append_unique_addr(uint8_t *addrs, int *n, int max, unsigned v)
456	{
457	  int i;
458	
459	  if (v < 1 || v > 247 || *n >= max)
460	    {
461	      return 0;
462	    }
463	
464	  for (i = 0; i < *n; i++)
465	    {
466	      if (addrs[i] == (uint8_t)v)
467	        {
468	          return 0;
469	        }
470	    }
471	
472	  addrs[(*n)++] = (uint8_t)v;
473	  return 1;
474	}
