476	static int parse_hits_array(FAR const char *json, uint8_t *addrs, int max)
477	{
478	  FAR const char *hits;
479	  FAR const char *p;
480	  char *end;
481	  int n = 0;
482	
483	  hits = strstr(json, "\"hits\":");
484	  if (hits == NULL)
485	    {
486	      return 0;
487	    }
488	
489	  p = strchr(hits, '[');
490	  if (p == NULL)
491	    {
492	      return 0;
493	    }
494	
495	  p++;
496	  while (*p != '\0' && *p != ']' && n < max)
497	    {
498	      while (*p == ' ' || *p == '\t' || *p == ',' || *p == '\n' || *p == '\r')
499	        {
500	          p++;
501	        }
502	
503	      if (*p == ']' || *p == '\0')
504	        {
505	          break;
506	        }
507	
508	      if (*p >= '0' && *p <= '9')
509	        {
510	          unsigned v = (unsigned)strtoul(p, &end, 10);
511	          if (end == p)
512	            {
513	              break;
514	            }
515	
516	          append_unique_addr(addrs, &n, max, v);
517	          p = end;
518	        }
519	      else
520	        {
521	          p++;
522	        }
523	    }
524	
525	  return n;
526	}
