528	static int parse_point_addrs(FAR const char *json, uint8_t *addrs, int max)
529	{
530	  FAR const char *p = json;
531	  int n = 0;
532	
533	  while ((p = strstr(p, "\"addr\":")) != NULL && n < max)
534	    {
535	      char *end;
536	      unsigned v;
537	
538	      p += 7;
539	      v = (unsigned)strtoul(p, &end, 10);
540	      if (end == p)
541	        {
542	          p++;
543	          continue;
544	        }
545	
546	      append_unique_addr(addrs, &n, max, v);
547	      p = end;
548	    }
549	
550	  return n;
551	}
