554	{
555	  FILE *fp;
556	  char buf[4096];
557	  size_t nread;
558	  int n;
559	
560	  if (path == NULL || path[0] == '\0' || addrs == NULL || max <= 0)

560	  if (path == NULL || path[0] == '\0' || addrs == NULL || max <= 0)
561	    {
562	      return -EINVAL;
563	    }
564	
