979	int vg_live_snapshot_write(FAR const char *path,
980	                           FAR const struct vg_live_snapshot *snap)
981	{
982	  char tmp[160];
983	  FILE *fp;
984	  int i;
985	  int n;
986	
987	  if (path == NULL || path[0] == '\0' || snap == NULL)
988	    {
989	      return -EINVAL;
990	    }
991	
992	  n = snap->n;
993	  if (n < 0)
994	    {
995	      n = 0;
996	    }
997	
998	  if (n > VG_DISCOVER_MAX_POINTS)
999	    {
1000	      n = VG_DISCOVER_MAX_POINTS;
1001	    }
1002	
1003	  (void)mkdir_parent(path);
1004	  snprintf(tmp, sizeof(tmp), "%s.tmp", path);
1005	  fp = fopen(tmp, "w");
1006	  if (fp == NULL)
1007	    {
1008	      return -errno;
1009	    }
1010	
1011	  if (fprintf(fp, "tick_ms=%u\nn=%d\n", (unsigned)snap->tick_ms, n) < 0)
1012	    {
1013	      fclose(fp);
1014	      unlink(tmp);
1015	      return -EIO;
1016	    }
1017	
1018	  for (i = 0; i < n; i++)
1019	    {
1020	      FAR const struct vg_live_sample *s = &snap->samples[i];
1021	      FAR const char *unit = (s->unit[0] != '\0') ? s->unit : "-";
1022	      int rc;
1023	
1024	      if (s->ok)
1025	        {
1026	          rc = fprintf(fp, "id=%s value=%.6g ok=1 unit=%s\n",
1027	                       s->id[0] ? s->id : "-", (double)s->value, unit);
1028	        }
1029	      else
1030	        {
1031	          rc = fprintf(fp, "id=%s value=- ok=0 unit=%s\n",
1032	                       s->id[0] ? s->id : "-", unit);
1033	        }
1034	
1035	      if (rc < 0)
1036	        {
1037	          fclose(fp);
1038	          unlink(tmp);
1039	          return -EIO;
1040	        }
1041	    }
1042	
1043	  if (fflush(fp) != 0)
1044	    {
1045	      fclose(fp);
1046	      unlink(tmp);
1047	      return -EIO;
1048	    }
1049	
1050	  fclose(fp);
1051	  if (rename(tmp, path) != 0)
1052	    {
1053	      int err = errno;
1054	
1055	      unlink(tmp);
1056	      return -err;
1057	    }
1058	
1059	  return 0;
1060	}
