1062	int vg_live_snapshot_read(FAR const char *path,
1063	                          FAR struct vg_live_snapshot *snap)
1064	{
1065	  FILE *fp;
1066	  char line[128];
1067	  int declared_n = -1;
1068	
1069	  if (path == NULL || path[0] == '\0' || snap == NULL)
1070	    {
1071	      return -EINVAL;
1072	    }
1073	
1074	  memset(snap, 0, sizeof(*snap));
1075	  fp = fopen(path, "r");
1076	  if (fp == NULL)
1077	    {
1078	      return (errno == ENOENT) ? -ENOENT : -errno;
1079	    }
1080	
1081	  while (fgets(line, sizeof(line), fp) != NULL)
1082	    {
1083	      size_t len = strlen(line);
1084	      unsigned tick;
1085	      unsigned ok;
1086	      char id[VG_POINT_ID_MAX];
1087	      char valstr[32];
1088	      char unit[8];
1089	      struct vg_live_sample *s;
1090	
1091	      while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r'))
1092	        {
1093	          line[--len] = '\0';
1094	        }
1095	
1096	      if (len == 0 || line[0] == '#')
1097	        {
1098	          continue;
1099	        }
1100	
1101	      if (sscanf(line, "tick_ms=%u", &tick) == 1)
1102	        {
1103	          snap->tick_ms = tick;
1104	          continue;
1105	        }
1106	
1107	      if (sscanf(line, "n=%d", &declared_n) == 1)
1108	        {
1109	          continue;
1110	        }
1111	
1112	      if (sscanf(line, "id=%23s value=%31s ok=%u unit=%7s",
1113	                 id, valstr, &ok, unit) != 4)
1114	        {
1115	          continue;
1116	        }
1117	
1118	      if (!vg_point_validate_id(id) || snap->n >= VG_DISCOVER_MAX_POINTS)
1119	        {

1119	        {
1120	          continue;
1121	        }
1122	
1123	      s = &snap->samples[snap->n];
1124	      memset(s, 0, sizeof(*s));
1125	      snprintf(s->id, sizeof(s->id), "%s", id);
1126	      if (unit[0] != '\0' && strcmp(unit, "-") != 0)
1127	        {
1128	          snprintf(s->unit, sizeof(s->unit), "%s", unit);
1129	        }
1130	
1131	      if (ok != 0 && strcmp(valstr, "-") != 0)
1132	        {
1133	          char *end = NULL;
1134	          float v = strtof(valstr, &end);
1135	
1136	          if (end != valstr && end != NULL && *end == '\0' && v == v)
1137	            {
1138	              s->ok = 1;
1139	              s->value = v;
1140	            }
1141	        }
1142	
1143	      snap->n++;
1144	    }
1145	
1146	  fclose(fp);
1147	  (void)declared_n;
1148	  return 0;
1149	}
