1193	static int json_copy_object(FAR const char *start, FAR char *out, size_t outsz)
1194	{
1195	  int depth = 0;
1196	  size_t n = 0;
1197	  FAR const char *p = start;
1198	
1199	  if (start == NULL || *start != '{' || out == NULL || outsz < 2)
1200	    {
1201	      return -EINVAL;
1202	    }
1203	
1204	  do
1205	    {
1206	      if (n + 1 >= outsz)
1207	        {
1208	          return -ENOSPC;
1209	        }
1210	
1211	      if (*p == '{')
1212	        {
1213	          depth++;
1214	        }
1215	      else if (*p == '}')
1216	        {
1217	          depth--;
1218	        }
1219	
1220	      out[n++] = *p++;
1221	    }
1222	  while (depth > 0 && *p != '\0');
1223	
1224	  if (depth != 0)
1225	    {
1226	      return -EINVAL;
1227	    }
1228	
1229	  out[n] = '\0';
1230	  return 0;
1231	}
