1233	static FAR const char *json_key(FAR const char *obj, FAR const char *key)
1234	{
1235	  char pat[40];
1236	  FAR const char *p;
1237	
1238	  if (obj == NULL || key == NULL)
1239	    {
1240	      return NULL;
1241	    }
1242	
1243	  snprintf(pat, sizeof(pat), "\"%s\"", key);
1244	  p = strstr(obj, pat);
1245	  if (p == NULL)
1246	    {
1247	      return NULL;
1248	    }
1249	
1250	  p += strlen(pat);
1251	  while (*p == ' ' || *p == '\t')
1252	    {
1253	      p++;
1254	    }
1255	
1256	  if (*p != ':')
1257	    {
1258	      return NULL;
1259	    }
1260	
1261	  p++;
1262	  while (*p == ' ' || *p == '\t')
1263	    {
1264	      p++;
1265	    }
1266	
1267	  return p;
1268	}
