1270	static int json_str(FAR const char *obj, FAR const char *key,
1271	                    FAR char *out, size_t outsz)
1272	{
1273	  FAR const char *p = json_key(obj, key);
1274	  size_t n = 0;
1275	
1276	  if (p == NULL || *p != '"' || out == NULL || outsz == 0)
1277	    {
1278	      return 0;
1279	    }
1280	
1281	  p++;
1282	  while (*p != '\0' && *p != '"' && n + 1 < outsz)
1283	    {
1284	      out[n++] = *p++;
1285	    }
1286	
1287	  out[n] = '\0';
1288	  return 1;
1289	}
