1334	static int parse_one_point(FAR const char *obj, FAR struct vg_point_entry *p)
1335	{
1336	  long v;
1337	  float f;
1338	  char tmp[24];
1339	
1340	  if (obj == NULL || p == NULL)
1341	    {
1342	      return -EINVAL;
1343	    }
1344	
1345	  point_defaults(p);
1346	  if (!json_str(obj, "id", p->id, sizeof(p->id)) ||
1347	      !vg_point_validate_id(p->id))
1348	    {
1349	      return -EINVAL;
1350	    }
1351	
1352	  if (json_str(obj, "name", p->name, sizeof(p->name)))
1353	    {
1354	      if (!vg_point_validate_name(p->name))
1355	        {
1356	          return -EINVAL;
1357	        }
1358	    }
1359	  else
1360	    {
1361	      memcpy(p->name, p->id, strlen(p->id) + 1);
1362	    }
1363	
1364	  if (!json_long(obj, "addr", &v) || v < 1 || v > 247)
1365	    {
1366	      return -EINVAL;
1367	    }
1368	
1369	  p->addr = (uint8_t)v;
1370	  if (json_long(obj, "fc", &v) && (v == 3 || v == 4))
1371	    {
1372	      p->fc = (uint8_t)v;
1373	    }
1374	
1375	  if (!json_long(obj, "reg", &v) || v < 0 || v > 65535)
1376	    {
1377	      return -EINVAL;
1378	    }
1379	
1380	  p->reg = (uint16_t)v;
1381	  if (json_long(obj, "qty", &v) && v >= 1 && v <= 4)
1382	    {
1383	      p->qty = (uint16_t)v;
1384	    }
1385	
1386	  if (json_str(obj, "dtype", tmp, sizeof(tmp)))
1387	    {
1388	      if (strcmp(tmp, "int16") == 0 || strcmp(tmp, "uint16") == 0)
1389	        {
1390	          memcpy(p->dtype, tmp, strlen(tmp) + 1);
1391	        }
1392	    }
1393	
1394	  if (json_float(obj, "scale", &f) && vg_finite_f(f))
1395	    {
1396	      p->scale = f;
1397	    }
1398	
1399	  (void)json_str(obj, "unit", p->unit, sizeof(p->unit));
1400	  if (json_str(obj, "cmp", tmp, sizeof(tmp)))
1401	    {
1402	      if (strcmp(tmp, "ge") == 0 || strcmp(tmp, "le") == 0 ||
1403	          strcmp(tmp, "eq") == 0)
1404	        {
1405	          memcpy(p->cmp, tmp, strlen(tmp) + 1);
1406	        }
1407	    }
1408	
1409	  if (json_float(obj, "warn", &f) && vg_finite_f(f))
1410	    {
1411	      p->has_warn = 1;
1412	      p->warn = f;
1413	    }
1414	
1415	  if (json_float(obj, "crit", &f) && vg_finite_f(f))
1416	    {
1417	      p->has_crit = 1;
1418	      p->crit = f;
1419	    }
1420	
1421	  if (json_long(obj, "fail_n", &v) && v >= 1 && v <= 20)
1422	    {
1423	      p->fail_n = (uint8_t)v;
1424	    }
1425	
1426	  return 0;
1427	}
