1429	int vg_point_table_read(FAR struct vg_discover_summary *sum,
1430	                        FAR const char *path)
1431	{
1432	  FILE *fp;
1433	  char *buf;
1434	  char obj[512];
1435	  size_t nread;
1436	  FAR const char *p;
1437	  FAR const char *arr;
1438	  long baud;
1439	  int ret = 0;
1440	
1441	  if (sum == NULL || path == NULL || path[0] == '\0')
1442	    {
1443	      return -EINVAL;
1444	    }
1445	
1446	  memset(sum, 0, sizeof(*sum));
1447	  sum->baud = 9600;
1448	  snprintf(sum->devpath, sizeof(sum->devpath), "/dev/rs485");
1449	
1450	  /* Heap: NSH vgpoint/vgdiscover stacks are 16K; a local 8K JSON buffer plus
1451	   * vg_discover_summary overflows and panics in IDLE. */
1452	  buf = (char *)malloc(VG_POINTS_JSON_MAX);
1453	  if (buf == NULL)
1454	    {
1455	      return -ENOMEM;
1456	    }
1457	
1458	  fp = fopen(path, "r");
1459	  if (fp == NULL)
1460	    {
1461	      ret = (errno != 0) ? -errno : -EIO;
1462	      goto out;
1463	    }
1464	
1465	  nread = fread(buf, 1, VG_POINTS_JSON_MAX - 1, fp);
1466	
1467	  /* A medium that fails mid-read gives a short count, not a short file.
1468	   * Without this the buffer just ends early and parses as a damaged table,
1469	   * which hides the I/O error behind a content complaint.
1470	   */
1471	
1472	  if (ferror(fp) != 0)
1473	    {
1474	      fclose(fp);
1475	      ret = -EIO;
1476	      goto out;
1477	    }
1478	
1479	  fclose(fp);
1480	  buf[nread] = '\0';
1481	  if (nread == VG_POINTS_JSON_MAX - 1)
1482	    {
1483	      ret = -EFBIG;
1484	      goto out;
1485	    }
1486	
1487	  if (json_str(buf, "device", sum->devpath, sizeof(sum->devpath)) == 0)
1488	    {
1489	      snprintf(sum->devpath, sizeof(sum->devpath), "/dev/rs485");
1490	    }
1491	
1492	  if (json_long(buf, "baud", &baud) && baud > 0)
1493	    {
1494	      sum->baud = (int)baud;
1495	    }
1496	
1497	  /* The file opened but carries no points array: it is truncated or not a
1498	   * point table at all.  Reporting that as a successful empty table let a
1499	   * damaged store masquerade as "no points", and let apply overwrite the
1500	   * committed table with zero points.
1501	   */
1502	
1503	  arr = strstr(buf, "\"points\"");
1504	  if (arr == NULL)
1505	    {
1506	      ret = -EINVAL;
1507	      goto out;
1508	    }
1509	
1510	  arr = strchr(arr, '[');
1511	  if (arr == NULL)
1512	    {
1513	      ret = -EINVAL;
1514	      goto out;
1515	    }
1516	
1517	  p = arr + 1;
1518	  while (*p != '\0' && *p != ']' && sum->n_points < VG_DISCOVER_MAX_POINTS)
1519	    {
1520	      while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r' || *p == ',')
1521	        {
1522	          p++;
1523	        }
1524	
1525	      if (*p == ']' || *p == '\0')
1526	        {
1527	          break;
1528	        }
1529	
1530	      if (*p != '{')
1531	        {
1532	          p++;
1533	          continue;
1534	        }
1535	
1536	      ret = json_copy_object(p, obj, sizeof(obj));
1537	      if (ret != 0)
1538	        {
1539	          goto out;
1540	        }
1541	
1542	      if (parse_one_point(obj, &sum->points[sum->n_points]) == 0 &&
1543	          vg_point_table_find_id(sum, sum->points[sum->n_points].id) < 0)
1544	        {
1545	          sum->n_points++;
1546	        }
1547	
1548	      p++;
1549	      {
1550	        int depth = 1;
1551	
1552	        while (*p != '\0' && depth > 0)
1553	          {
1554	            if (*p == '{')
1555	              {
1556	                depth++;
1557	              }
1558	            else if (*p == '}')
1559	              {
1560	                depth--;
1561	              }
1562	
1563	            p++;
1564	          }
1565	      }
1566	    }
1567	
1568	out:
1569	  free(buf);
1570	  return ret;
1571	}
1572	
1573	int vg_point_table_ensure_candidate(FAR struct vg_discover_summary *sum,
1574	                                    FAR const char *cand_path,
1575	                                    FAR const char *committed_path)
1576	{
1577	  int ret;
1578	
1579	  if (sum == NULL || cand_path == NULL)
1580	    {
1581	      return -EINVAL;
1582	    }
1583	
1584	  ret = vg_point_table_read(sum, cand_path);
1585	  if (ret == 0)
1586	    {
1587	      return 0;
1588	    }
1589	
1590	  /* Only "no candidate yet" falls through to seeding from the committed
1591	   * table.  A candidate that exists but cannot be read must not be treated
1592	   * as an empty one: the caller would hand back a fresh table, and the next
1593	   * apply --confirm would write it over the committed points.
1594	   */
1595	
1596	  if (ret != -ENOENT)
1597	    {
1598	      return ret;
1599	    }
1600	
1601	  if (committed_path != NULL)
1602	    {
1603	      ret = vg_point_table_read(sum, committed_path);
1604	      if (ret == 0)
1605	        {
1606	          return vg_point_table_write_candidate(sum, cand_path);
1607	        }
1608	
1609	      if (ret != -ENOENT)
1610	        {
1611	          return ret;
1612	        }
1613	    }
1614	
1615	  memset(sum, 0, sizeof(*sum));
1616	  sum->baud = 9600;
1617	  snprintf(sum->devpath, sizeof(sum->devpath), "/dev/rs485");
1618	  return vg_point_table_write_candidate(sum, cand_path);

