80	static int flag_index(int argc, char *argv[], int start, FAR const char *flag)
81	{
82	  int i;
83	
84	  for (i = start; i < argc; i++)
85	    {
86	      if (strcmp(argv[i], flag) == 0)
87	        {
88	          return i;
89	        }
90	    }
91	
92	  return -1;
93	}
