95	static int flag_value(int argc, char *argv[], int start,
96	                      FAR const char *flag, FAR const char **out)
97	{
98	  int i = flag_index(argc, argv, start, flag);
99	
100	  if (i < 0)
101	    {
102	      return 0;
103	    }
104	
105	  if (i + 1 >= argc)
106	    {
107	      return -1;
108	    }
109	
110	  *out = argv[i + 1];
111	  return 1;
112	}
