114	static int parse_long_range(FAR const char *s, long minv, long maxv, long *out)
115	{
116	  char *end;
117	  long v;
118	
119	  if (s == NULL || out == NULL)
120	    {
121	      return -1;
122	    }
123	
124	  v = strtol(s, &end, 0);
125	  if (end == s || *end != '\0' || v < minv || v > maxv)
126	    {
127	      return -1;
128	    }
129	
130	  *out = v;
131	  return 0;
132	}
133	
134	static int parse_float_val(FAR const char *s, float *out)
135	{
136	  char *end;
137	  float v;
138	
139	  if (s == NULL || out == NULL)
140	    {
141	      return -1;
142	    }
143	
144	  v = strtof(s, &end);
145	  if (end == s || *end != '\0' || v != v)
146	    {
147	      return -1;
148	    }
149	
150	  *out = v;
151	  return 0;
152	}
