154	static int apply_common_fields(int argc, char *argv[], int start,
155	                               FAR struct vg_point_entry *p, int *touched)
156	{
157	  FAR const char *val;
158	  int rc;
159	  long v;
160	  float f;
161	
162	  rc = flag_value(argc, argv, start, "-a", &val);
163	  if (rc < 0)
164	    {
165	      return -1;
166	    }
167	
168	  if (rc > 0)
169	    {
170	      if (parse_long_range(val, 1, 247, &v) != 0)
171	        {
172	          return -1;
173	        }
174	
175	      p->addr = (uint8_t)v;
176	      if (touched)
177	        {
178	          *touched = 1;
179	        }
180	    }
181	
182	  rc = flag_value(argc, argv, start, "-r", &val);
183	  if (rc < 0)
184	    {
185	      return -1;
186	    }
187	
188	  if (rc > 0)
189	    {
190	      if (parse_long_range(val, 0, 65535, &v) != 0)
191	        {
192	          return -1;
193	        }
194	
195	      p->reg = (uint16_t)v;
196	      if (touched)
197	        {
198	          *touched = 1;
199	        }
200	    }
201	
202	  rc = flag_value(argc, argv, start, "-f", &val);
203	  if (rc < 0)
204	    {
205	      return -1;
206	    }
207	
208	  if (rc > 0)
209	    {
210	      if (parse_long_range(val, 3, 4, &v) != 0 || (v != 3 && v != 4))
211	        {
212	          return -1;
213	        }
214	
215	      p->fc = (uint8_t)v;
216	      if (touched)
217	        {
218	          *touched = 1;
219	        }
220	    }
221	
222	  rc = flag_value(argc, argv, start, "-q", &val);
223	  if (rc < 0)
224	    {
225	      return -1;
226	    }
227	
228	  if (rc > 0)
229	    {
230	      if (parse_long_range(val, 1, 4, &v) != 0)
231	        {
232	          return -1;
233	        }
234	
235	      p->qty = (uint16_t)v;
236	      if (touched)
237	        {
238	          *touched = 1;
239	        }
240	    }
241	
242	  rc = flag_value(argc, argv, start, "-d", &val);
243	  if (rc < 0)
244	    {
245	      return -1;
246	    }
247	
248	  if (rc > 0)
249	    {
250	      if (strcmp(val, "int16") != 0 && strcmp(val, "uint16") != 0)
251	        {
252	          return -1;
253	        }
254	
255	      snprintf(p->dtype, sizeof(p->dtype), "%s", val);
256	      if (touched)
257	        {
258	          *touched = 1;
259	        }
260	    }
261	
262	  rc = flag_value(argc, argv, start, "-s", &val);
263	  if (rc < 0)
264	    {
265	      return -1;
266	    }
267	
268	  if (rc > 0)
269	    {
270	      if (parse_float_val(val, &f) != 0)
271	        {
272	          return -1;
273	        }
274	
275	      p->scale = f;
276	      if (touched)
277	        {
278	          *touched = 1;
279	        }
280	    }
281	
282	  rc = flag_value(argc, argv, start, "-u", &val);
283	  if (rc < 0)
284	    {
285	      return -1;
286	    }
287	
288	  if (rc > 0)
289	    {
290	      if (strlen(val) > 7)
291	        {
292	          return -1;
293	        }
294	
295	      snprintf(p->unit, sizeof(p->unit), "%s", val);
296	      if (touched)
297	        {
298	          *touched = 1;
299	        }
300	    }
301	
302	  rc = flag_value(argc, argv, start, "-k", &val);
303	  if (rc < 0)
304	    {
305	      return -1;
306	    }
307	
308	  if (rc > 0)
309	    {
310	      if (strcmp(val, "-") == 0)
311	        {
312	          p->cmp[0] = '\0';
313	        }
314	      else if (strcmp(val, "ge") == 0 || strcmp(val, "le") == 0 ||
315	               strcmp(val, "eq") == 0)
316	        {
317	          snprintf(p->cmp, sizeof(p->cmp), "%s", val);
318	        }
319	      else
320	        {
321	          return -1;
322	        }
323	
324	      if (touched)
325	        {
326	          *touched = 1;
327	        }
328	    }
329	
330	  rc = flag_value(argc, argv, start, "-w", &val);
331	  if (rc < 0)
332	    {
333	      return -1;
334	    }
335	
336	  if (rc > 0)
337	    {
338	      if (strcmp(val, "-") == 0)
339	        {
340	          p->has_warn = 0;
341	          p->warn = 0.0f;
342	        }
343	      else if (parse_float_val(val, &f) != 0)
344	        {
345	          return -1;
346	        }
347	      else
348	        {
349	          p->has_warn = 1;
350	          p->warn = f;
351	        }
352	
353	      if (touched)
354	        {
355	          *touched = 1;
356	        }
357	    }
358	
359	  rc = flag_value(argc, argv, start, "-C", &val);
360	  if (rc < 0)
361	    {
362	      return -1;
363	    }
364	
365	  if (rc > 0)
366	    {
367	      if (strcmp(val, "-") == 0)
368	        {
369	          p->has_crit = 0;
370	          p->crit = 0.0f;
371	        }
372	      else if (parse_float_val(val, &f) != 0)
373	        {
374	          return -1;
375	        }
376	      else
377	        {
378	          p->has_crit = 1;
379	          p->crit = f;
380	        }
381	
382	      if (touched)
383	        {
384	          *touched = 1;
385	        }
386	    }
387	
388	  rc = flag_value(argc, argv, start, "-N", &val);
389	  if (rc < 0)
390	    {
391	      return -1;
392	    }
393	
394	  if (rc > 0)
395	    {
396	      if (!vg_point_validate_name(val))
397	        {
398	          return -1;
399	        }
400	
401	      snprintf(p->name, sizeof(p->name), "%s", val);
402	      if (touched)
403	        {
404	          *touched = 1;
405	        }
406	    }
407	
408	  rc = flag_value(argc, argv, start, "-n", &val);
409	  if (rc < 0)
410	    {
411	      return -1;
412	    }
413	
414	  if (rc > 0)
415	    {
416	      if (parse_long_range(val, 1, 20, &v) != 0)
417	        {
418	          return -1;
419	        }
420	
421	      p->fail_n = (uint8_t)v;
422	      if (touched)
423	        {
424	          *touched = 1;
425	        }
426	    }
427	
428	  if (p->fail_n < 1)
429	    {
430	      p->fail_n = 3;
431	    }
432	
433	  if (p->fc == 0)
434	    {
435	      p->fc = 3;
436	    }
437	
438	  if (p->qty == 0)
439	    {
440	      p->qty = 1;
441	    }
442	
443	  if (p->dtype[0] == '\0')
444	    {
445	      snprintf(p->dtype, sizeof(p->dtype), "int16");
446	    }
447	
448	  return 0;
449	}
