451	static int cmd_list(int argc, char *argv[])
452	{
453	  struct vg_discover_summary sum;
454	  FAR const char *path = CONFIG_VG_DISCOVER_POINTS_PATH;
455	  FAR const char *table = "committed";
456	  char line[256];
457	  int i;
458	  int ret;
459	
460	  if (flag_index(argc, argv, 2, "-c") >= 0)
461	    {
462	      path = CONFIG_VG_DISCOVER_CANDIDATE_PATH;
463	      table = "candidate";
464	    }
465	
466	  ret = vg_point_table_read(&sum, path);
467	  if (ret == -ENOENT)
468	    {
469	      /* A missing table counts as a legitimately empty one only while the
470	       * store is really there.  A dangling /data symlink, or a store that
471	       * fell back to RAM, also answers "no such file" - and a table that
472	       * does not survive a reboot is a failure, not zero points.
473	       */
474	
475	      ret = vg_point_store_root_ok(CONFIG_VG_STORE_ROOT);
476	      if (ret == 0)
477	        {
478	          memset(&sum, 0, sizeof(sum));
479	        }
480	    }
481	
482	  if (ret != 0)
483	    {
484	      return reply_err("list", "io", vg_point_table_err_token(ret));
485	    }
486	
487	  for (i = 0; i < sum.n_points; i++)
488	    {
489	      vg_point_format_point(line, sizeof(line), &sum.points[i]);
490	      printf("%s\n", line);
491	    }
492	
493	  reply_ok("list", table, sum.n_points);
494	  return 0;
495	}
