497	static int cmd_add(int argc, char *argv[])
498	{
499	  struct vg_discover_summary sum;
500	  FAR const char *id = NULL;
501	  FAR struct vg_point_entry *p;
502	  int rc;
503	
504	  if (flag_value(argc, argv, 2, "-i", &id) <= 0 ||
505	      !vg_point_validate_id(id))
506	    {
507	      return reply_err("add", "bad_arg", "bad_id");
508	    }
509	
510	  rc = vg_point_table_ensure_candidate(&sum,
511	                                       CONFIG_VG_DISCOVER_CANDIDATE_PATH,
512	                                       CONFIG_VG_DISCOVER_POINTS_PATH);
513	  if (rc != 0)
514	    {
515	      return reply_err("add", "io", vg_point_table_err_token(rc));
516	    }
517	
518	  if (vg_point_table_find_id(&sum, id) >= 0)
519	    {
520	      return reply_err("add", "dup_id", "id_exists");
521	    }
522	
523	  if (sum.n_points >= VG_DISCOVER_MAX_POINTS)
524	    {
525	      return reply_err("add", "full", "table_full");
526	    }
527	
528	  p = &sum.points[sum.n_points];
529	  memset(p, 0, sizeof(*p));
530	  snprintf(p->id, sizeof(p->id), "%s", id);
531	  p->fc = 3;
532	  p->qty = 1;
533	  p->scale = 1.0f;
534	  p->fail_n = 3;
535	  snprintf(p->dtype, sizeof(p->dtype), "int16");
536	
537	  if (apply_common_fields(argc, argv, 2, p, NULL) != 0 ||
