1	/****************************************************************************
2	 * app/velaguard/modbus_port_openvela.c
3	 *
4	 * nanoMODBUS 串口适配层：把 /dev/rs485 接到 nmbs_platform_conf 的
5	 * read/write/flush。不含任何 Modbus 协议逻辑。
6	 *
7	 * 传输契约（nanoMODBUS v1.23.0）：
8	 *   - 阻塞到收满/发完 count 字节，或 byte_timeout_ms 到期；
9	 *   - byte_timeout_ms < 0 无限等待，== 0 非阻塞试一次；
10	 *   - 返回实际字节数；< 0 为传输错误；[0, count-1] 视为超时。
11	 *
12	 * DE/RE 由 NuttX UART7 RS485 驱动在 TC 后切换。tcdrain 在 RS485 下等到
13	 * TC；其后短延时仅为 Modbus RTU 帧间隔（3.5 字符），不是 DIR 补偿。
14	 ****************************************************************************/
15	
16	#include <nuttx/config.h>
17	
18	#include <errno.h>
19	#include <fcntl.h>
20	#include <poll.h>
21	#include <stdbool.h>
22	#include <stdint.h>
23	#include <termios.h>
24	#include <time.h>
25	#include <unistd.h>
26	
27	#include "modbus_port_openvela.h"
28	
29	/****************************************************************************
30	 * Private Functions
31	 ****************************************************************************/
32	
33	static int32_t vg_modbus_now_ms(void)
34	{
35	  struct timespec ts;
36	
37	  clock_gettime(CLOCK_MONOTONIC, &ts);
38	  return (int32_t)(ts.tv_sec * 1000L + ts.tv_nsec / 1000000L);
39	}
40	
41	/* After TC the transceiver DIR falls; a short settle then drop RX junk
42	 * (0xFF/FE glitches) before waiting for the slave.  Do not sit  several
43	 * ms with DIR=RX without flushing: those bytes prepend onto the next PDU
44	 * and look like a CRC error in Modbus Slave. */
45	
46	#define VG_MODBUS_DIR_SETTLE_US 500
47	
48	static int32_t vg_modbus_port_read(uint8_t *buf, uint16_t count,
49	                                   int32_t byte_timeout_ms, void *arg)
50	{
51	  FAR struct vg_modbus_port_s *port = arg;
52	  uint16_t got = 0;
53	  int32_t deadline = 0;
54	  bool infinite = (byte_timeout_ms < 0);
55	
56	  if (port == NULL || port->fd < 0 || buf == NULL)
57	    {
58	      return -1;
59	    }
60	
61	  if (count == 0)
62	    {
63	      return 0;
64	    }
65	
66	  if (!infinite)
67	    {
68	      deadline = vg_modbus_now_ms() + byte_timeout_ms;
69	    }
70	
71	  while (got < count)
72	    {
73	      struct pollfd pfd;
74	      int remain;
75	      int ret;
76	      ssize_t n;
77	
78	      if (infinite)
79	        {
80	          remain = 1000;
81	        }
82	      else
83	        {
84	          remain = (int)(deadline - vg_modbus_now_ms());
85	          if (remain < 0)
86	            {
87	              remain = 0;
88	            }
89	        }
90	
91	      pfd.fd      = port->fd;
92	      pfd.events  = POLLIN;
93	      pfd.revents = 0;
94	
95	      ret = poll(&pfd, 1, remain);
96	      if (ret < 0)
97	        {
98	          if (errno == EINTR)
99	            {
100	              continue;
101	            }
102	
103	          return -1;
104	        }
105	
106	      if (ret == 0)
107	        {
108	          if (infinite)
109	            {
110	              continue;
111	            }
112	
113	          return got;
114	        }
115	
116	      n = read(port->fd, buf + got, count - got);
117	      if (n > 0)
118	        {
119	          got += (uint16_t)n;
120	          continue;
121	        }
122	
123	      if (n == 0)
124	        {
125	          return got;
126	        }
127	
128	      if (errno == EAGAIN || errno == EINTR)
129	        {
130	          continue;
131	        }
132	
133	      return -1;
134	    }
135	
136	  return got;
137	}
138	
139	static int32_t vg_modbus_port_write(const uint8_t *buf, uint16_t count,
140	                                    int32_t byte_timeout_ms, void *arg)
141	{
142	  FAR struct vg_modbus_port_s *port = arg;
143	  uint16_t sent = 0;
144	  int32_t deadline = 0;
145	  bool infinite = (byte_timeout_ms < 0);
146	
147	  if (port == NULL || port->fd < 0 || buf == NULL)
148	    {
149	      return -1;
150	    }
151	
152	  if (count == 0)
153	    {
154	      return 0;
155	    }
156	
157	  if (!infinite)
158	    {
159	      deadline = vg_modbus_now_ms() + byte_timeout_ms;
160	    }
161	
162	  while (sent < count)
163	    {
164	      struct pollfd pfd;
165	      int remain;
166	      int ret;
167	      ssize_t n;
168	
169	      if (infinite)
170	        {
171	          remain = 1000;
172	        }
173	      else
174	        {
175	          remain = (int)(deadline - vg_modbus_now_ms());
176	          if (remain < 0)
177	            {
178	              remain = 0;
179	            }
180	        }
181	
182	      pfd.fd      = port->fd;
183	      pfd.events  = POLLOUT;
184	      pfd.revents = 0;
185	
186	      ret = poll(&pfd, 1, remain);
187	      if (ret < 0)
188	        {
189	          if (errno == EINTR)
190	            {
191	              continue;
192	            }
193	
194	          return -1;
195	        }
196	
197	      if (ret == 0)
198	        {
199	          if (infinite)
200	            {
201	              continue;
202	            }
203	
204	          return sent;
205	        }
206	
207	      n = write(port->fd, buf + sent, count - sent);
208	      if (n > 0)
209	        {
210	          sent += (uint16_t)n;
211	          continue;
212	        }
213	
214	      if (n == 0)
215	        {
216	          return sent;
217	        }
218	
219	      if (errno == EAGAIN || errno == EINTR)
220	        {
221	          continue;
222	        }
223	
224	      return -1;
225	    }
226	
227	  if (tcdrain(port->fd) < 0)
228	    {
229	      return -1;
230	    }
231	
232	  usleep(VG_MODBUS_DIR_SETTLE_US);
233	  tcflush(port->fd, TCIFLUSH);
234	  return sent;
235	}
236	
237	static void vg_modbus_port_flush(nmbs_t *nmbs, void *arg)
238	{
239	  FAR struct vg_modbus_port_s *port = arg;
240	  uint8_t tmp[32];
241	
242	  (void)nmbs;
243	
244	  if (port == NULL || port->fd < 0)
245	    {
246	      return;
247	    }
248	
249	  for (; ; )
250	    {
251	      struct pollfd pfd;
252	      ssize_t n;
253	
254	      pfd.fd      = port->fd;
255	      pfd.events  = POLLIN;
256	      pfd.revents = 0;
257	
258	      if (poll(&pfd, 1, 0) <= 0)
259	        {
260	          break;
261	        }
262	
263	      n = read(port->fd, tmp, sizeof(tmp));
264	      if (n <= 0)
265	        {
266	          break;
267	        }
268	    }
269	
270	  tcflush(port->fd, TCIFLUSH);
271	}
