273	/****************************************************************************
274	 * Public Functions
275	 ****************************************************************************/
276	
277	int vg_modbus_port_open(FAR struct vg_modbus_port_s *port,
278	                        FAR const char *devpath)
279	{
280	  struct termios tio;
281	  int fd;
282	
283	  if (port == NULL || devpath == NULL)
284	    {
285	      return -1;
286	    }
287	
288	  fd = open(devpath, O_RDWR);
289	  if (fd < 0)
290	    {
291	      return -1;
292	    }
293	
294	  if (tcgetattr(fd, &tio) < 0)
295	    {
296	      close(fd);
297	      return -1;
298	    }
299	
