/* Adversarial probe of the discovery point-table JSON layer.
 * Not part of the repo; scratch review harness.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "vg_discover.h"

static int fails;

static void ck(int cond, const char *msg)
{
  printf("%s %s\n", cond ? "[ok  ]" : "[FAIL]", msg);
  if (!cond)
    {
      fails++;
    }
}

static struct vg_discover_summary mk(void)
{
  struct vg_discover_summary s;

  memset(&s, 0, sizeof(s));
  s.baud = 9600;
  snprintf(s.devpath, sizeof(s.devpath), "/dev/rs485");
  return s;
}

static void add(struct vg_discover_summary *s, const char *id, const char *unit,
                float scale, int has_warn, float warn)
{
  struct vg_point_entry *p = &s->points[s->n_points++];

  memset(p, 0, sizeof(*p));
  snprintf(p->id, sizeof(p->id), "%s", id);
  snprintf(p->name, sizeof(p->name), "%s", id);
  snprintf(p->dtype, sizeof(p->dtype), "int16");
  p->addr = 1;
  p->fc = 3;
  p->reg = 0;
  p->qty = 1;
  p->scale = scale;
  p->fail_n = 3;
  snprintf(p->unit, sizeof(p->unit), "%s", unit);
  p->has_warn = has_warn;
  p->warn = warn;
}

/* Round trip through the writer and reader.  Returns the reader's error. */
static int roundtrip(struct vg_discover_summary *in,
                     struct vg_discover_summary *out, const char *path)
{
  int ret;

  ret = vg_point_table_write_candidate(in, path);
  if (ret != 0)
    {
      printf("       write_candidate -> %d\n", ret);
      return ret;
    }

  return vg_point_table_read(out, path);
}

int main(void)
{
  struct vg_discover_summary a;
  struct vg_discover_summary b;
  char path[] = "/tmp/vgdisc-review/rt.json";

  /* --- 1. unit accepted by vgpoint -u (<=7 chars) but hostile to JSON --- */

  a = mk();
  add(&a, "t1", "x}y", 1.0f, 0, 0);
  printf("-- unit containing '}' --\n");
  printf("       read -> %d\n", roundtrip(&a, &b, path));
  ck(vg_point_table_read(&b, path) == 0, "unit 'x}y' table still readable");

  a = mk();
  add(&a, "t2", "{", 1.0f, 0, 0);
  printf("-- unit containing '{' --\n");
  printf("       read -> %d\n", roundtrip(&a, &b, path));
  ck(vg_point_table_read(&b, path) == 0, "unit '{' table still readable");

  a = mk();
  add(&a, "t3", "a\"b", 1.0f, 0, 0);
  printf("-- unit containing quote --\n");
  printf("       read -> %d\n", roundtrip(&a, &b, path));
  if (vg_point_table_read(&b, path) == 0)
    {
      printf("       unit read back as '%s'\n", b.points[0].unit);
      ck(strcmp(b.points[0].unit, "a\"b") == 0, "unit quote round trips");
    }

  a = mk();
  add(&a, "t4", "a,b", 1.0f, 0, 0);
  printf("-- unit containing comma --\n");

  /* --- 2. scale precision through %.3f --- */

  a = mk();
  add(&a, "s1", "A", 0.0001f, 0, 0);
  if (roundtrip(&a, &b, path) == 0)
    {
      printf("       scale 0.0001 read back as %.8g\n", (double)b.points[0].scale);
      ck(b.points[0].scale == 0.0001f, "scale 0.0001 survives the writer");
    }

  a = mk();
  add(&a, "s2", "A", 0.0015f, 0, 0);
  if (roundtrip(&a, &b, path) == 0)
    {
      printf("       scale 0.0015 read back as %.8g\n", (double)b.points[0].scale);
      ck(b.points[0].scale == 0.0015f, "scale 0.0015 survives the writer");
    }

  /* --- 3. non-finite thresholds, as accepted by vgpoint -w / -s --- */

  a = mk();
  add(&a, "w1", "C", 1.0f, 1, 1.0e40f);   /* strtof("1e40") -> inf */
  if (roundtrip(&a, &b, path) == 0)
    {
      printf("       warn 1e40 -> has_warn=%u warn=%g\n",
             (unsigned)b.points[0].has_warn, (double)b.points[0].warn);
      ck(b.points[0].has_warn == 1, "warn=inf is rejected, not silently dropped");
    }

  a = mk();
  add(&a, "w2", "C", 1.0e40f, 0, 0);
  if (roundtrip(&a, &b, path) == 0)
    {
      printf("       scale 1e40 -> scale=%g\n", (double)b.points[0].scale);
      ck(b.points[0].scale == 1.0e40f, "scale=inf preserved or rejected loudly");
    }

  /* --- 4. reader rejects the whole table when one object exceeds 512 --- */

  {
    FILE *fp = fopen(path, "w");

    if (fp != NULL)
      {
        int i;

        fputs("{\"schema_version\":1,\"points\":[", fp);
        for (i = 0; i < 600; i++)
          {
            fputs("\"pad\":\"0123456789\",", fp);
          }

        fputs("\"id\":\"big\",\"addr\":1,\"reg\":0}]}\n", fp);
        fclose(fp);
      }

    printf("-- oversized point object --\n");
    printf("       read -> %d\n", vg_point_table_read(&b, path));
    ck(vg_point_table_read(&b, path) == 0,
       "unknown extra keys do not kill the whole table");
  }

  /* --- 5. duplicate ids in one file --- */

  {
    FILE *fp = fopen(path, "w");

    if (fp != NULL)
      {
        fputs("{\"points\":["
              "{\"id\":\"d\",\"addr\":1,\"reg\":0},"
              "{\"id\":\"d\",\"addr\":1,\"reg\":5},"
              "{\"id\":\"e\",\"addr\":1,\"reg\":6}]}\n", fp);
        fclose(fp);
      }

    printf("-- duplicate ids --\n");
    printf("       read -> %d n_points=%d\n", vg_point_table_read(&b, path),
           b.n_points);
    ck(b.n_points == 2, "duplicate id dropped");
  }

  /* --- 6. address range parser edges --- */

  {
    int lo = 0;
    int hi = 0;

    ck(vg_discover_parse_addr_range("1-2-3", &lo, &hi) == false,
       "rejects 1-2-3");
    ck(vg_discover_parse_addr_range("1 - 8", &lo, &hi) == false,
       "rejects spaced range");
    ck(vg_discover_parse_addr_range("", &lo, &hi) == false, "rejects empty");
    ck(vg_discover_parse_addr_range("abc", &lo, &hi) == false, "rejects abc");
    ck(vg_discover_parse_addr_range("247-247", &lo, &hi) == true, "accepts 247");
    ck(vg_discover_parse_addr_range("248", &lo, &hi) == false, "rejects 248");
    ck(vg_discover_parse_addr_range("0x10", &lo, &hi) == true && lo == 16,
       "hex accepted");
    printf("       '1-2-3' -> lo=%d hi=%d\n", lo, hi);
  }

  /* --- 7. id/name length boundaries vs the writer --- */

  {
    char id[64];

    memset(id, 'a', sizeof(id));
    id[23] = '\0';
    ck(vg_point_validate_id(id) == 1, "id of 23 chars valid");
    id[24] = '\0';
    ck(vg_point_validate_id(id) == 0, "id of 24 chars invalid");

    ck(vg_point_validate_name("boiler") == 1, "plain name valid");
    ck(vg_point_validate_name("boiler 1") == 0, "name with space invalid");
  }

  remove(path);

  if (fails == 0)
    {
      printf("t1_table: all probes behaved\n");
    }
  else
    {
      printf("t1_table: %d probe(s) failed\n", fails);
    }

  return fails != 0;
}

"""Mock Modbus RTU slave on a PTY, for driving the velaguard discovery CLI.

Not part of the repo; scratch review harness.
"""
import os
import pty
import select
import struct
import subprocess
import sys
import threading
import time

LINK = "/tmp/vgdisc-review/rs485"


def crc16(data: bytes) -> int:
    crc = 0xFFFF
    for b in data:
        crc ^= b
        for _ in range(8):
            if crc & 1:
                crc = (crc >> 1) ^ 0xA001
            else:
                crc >>= 1
    return crc


def crc_bytes(data: bytes) -> bytes:
    c = crc16(data)
    return struct.pack("<H", c)


class Slave:
    """One modelled slave."""

    def __init__(self, addr, holding=None, input_regs=None, fc_supported=(3, 4),
                 start_limit=None, delay_ms=3, exc_for=None, bad_crc=False,
                 silent=False):
        self.addr = addr
        self.holding = holding or {}
        self.input_regs = input_regs or {}
        self.fc_supported = fc_supported
        self.start_limit = start_limit   # respond only when start < limit
        self.delay_ms = delay_ms
        self.exc_for = exc_for or {}     # (fc, start) -> exception code
        self.bad_crc = bad_crc
        self.silent = silent

    def regs_for(self, fc):
        return self.holding if fc == 3 else self.input_regs

    def respond(self, fc, start, qty):
        if self.silent:
            return None
        if fc not in self.fc_supported:
            return bytes([fc | 0x80, 1])
        if (fc, start) in self.exc_for:
            return bytes([fc | 0x80, self.exc_for[(fc, start)]])
        if self.start_limit is not None and start >= self.start_limit:
            return bytes([fc | 0x80, 2])
        regs = self.regs_for(fc)
        values = []
        for r in range(start, start + qty):
            if r not in regs:
                return bytes([fc | 0x80, 2])
            values.append(regs[r])
        body = bytes([fc, len(values) * 2]) + b"".join(
            struct.pack(">H", v) for v in values)
        return body


class MockBus(threading.Thread):
    def __init__(self, slaves, delay_scale=1.0, log=None):
        super().__init__(daemon=True)
        self.slaves = {s.addr: s for s in slaves}
        self.delay_scale = delay_scale
        self.log = log if log is not None else []
        self.stop_flag = False
        self.master, self.slave = pty.openpty()
        self.name = os.ttyname(self.slave)
        if os.path.islink(LINK) or os.path.exists(LINK):
            os.unlink(LINK)
        os.symlink(self.name, LINK)

    def run(self):
        buf = bytearray()
        while not self.stop_flag:
            r, _, _ = select.select([self.master], [], [], 0.05)
            if not r:
                continue
            try:
                chunk = os.read(self.master, 256)
            except OSError:
                return
            if not chunk:
                return
            buf.extend(chunk)
            self._drain(buf)

    def _drain(self, buf):
        # RTU frames: we only ever receive 8-byte read requests here.
        while len(buf) >= 8:
            frame = bytes(buf[:8])
            del buf[:8]
            self._handle(frame)

    def _handle(self, frame):
        addr = frame[0]
        crc_ok = frame[-2:] == crc_bytes(frame[:-2])
        self.log.append(("req", addr, frame.hex(), crc_ok))
        if not crc_ok:
            return
        slave = self.slaves.get(addr)
        if slave is None:
            return
        if frame[1] not in (3, 4):
            return
        start = struct.unpack(">H", frame[2:4])[0]
        qty = struct.unpack(">H", frame[4:6])[0]
        body = slave.respond(frame[1], start, qty)
        if body is None:
            self.log.append(("no-reply", addr, frame[1], start, qty))
            return
        resp = bytes([addr]) + body
        resp += crc_bytes(resp)
        if slave.bad_crc:
            resp = resp[:-1] + bytes([resp[-1] ^ 0xFF])
        time.sleep(slave.delay_ms / 1000.0 * self.delay_scale)
        try:
            os.write(self.master, resp)
        except OSError:
            pass
        self.log.append(("resp", addr, resp.hex()))

    def close(self):
        self.stop_flag = True
        self.join(timeout=1.0)
        os.close(self.master)
        os.close(self.slave)


def run_cli(argv, timeout=120):
    t0 = time.time()
    p = subprocess.run(argv, capture_output=True, text=True, timeout=timeout)
    return {
        "argv": argv,
        "rc": p.returncode,
        "out": p.stdout,
        "err": p.stderr,
        "secs": time.time() - t0,
    }


def show(title, res):
    print(f"===== {title}")
    print(f"  $ {' '.join(res['argv'][1:])}")
    print(f"  rc={res['rc']}  {res['secs']:.2f}s")
    for line in res["out"].strip().splitlines():
        print(f"  | {line}")
    for line in res["err"].strip().splitlines():
        print(f"  ! {line}")

