/* Proof: the vgdiscover/vgscan runtime path never consults the RS485 bus lock.
 * Holds the lock the way vgpoint test / the HMI poller / the collector do,
 * then runs the discovery calls that share the same /dev/rs485.
 */
#include <stdio.h>
#include <string.h>

#include "vg_discover.h"

#define DEV "/tmp/vgdisc-review/rs485"

int main(void)
{
  struct vg_discover_summary *sum = vg_discover_state();
  uint16_t vals[4];
  int rc;

  printf("vg_bus_is_locked before   = %d\n", vg_bus_is_locked());

  if (vg_bus_try_lock() != 0)
    {
      printf("could not take the lock\n");
      return 1;
    }

  printf("vg_bus_is_locked held     = %d\n", vg_bus_is_locked());

  vg_discover_reset(sum);
  rc = vg_bus_scan(sum, DEV, 9600, 1, 1, 5);
  printf("vg_bus_scan while locked  -> rc=%d hits=%d   %s\n", rc,
         sum->n_hits,
         (rc >= 0 && sum->n_hits > 0) ? "(DROVE THE BUS ANYWAY)" : "");

  vg_discover_reset(sum);
  rc = vg_reg_probe_slave(sum, DEV, 9600, 1, 3, 32);
  printf("vg_reg_probe_slave        -> rc=%d blocks=%d %s\n", rc,
         sum->n_blocks, (sum->n_blocks > 0) ? "(DROVE THE BUS ANYWAY)" : "");

  rc = vg_discover_test_read(DEV, 9600, 1, 0, 2, vals);
  printf("vg_discover_test_read     -> rc=%d v0=%u      %s\n", rc,
         (unsigned)vals[0], (rc == 0) ? "(DROVE THE BUS ANYWAY)" : "");

  /* vgpoint's own gate for comparison */
  rc = vg_bus_try_lock();
  printf("vgpoint-style second take -> rc=%d (EBUSY=%d) %s\n", rc, -EBUSY,
         (rc != 0) ? "(correctly refused)" : "(NOT EXCLUSIVE)");

  vg_bus_unlock();
  printf("vg_bus_is_locked released = %d\n", vg_bus_is_locked());
  return 0;
}

