/* Replays the HMI "Scan Bus -> Apply" loop: scan, then probe every hit with
 * fc=3 / reg_max=32 into one shared summary, then infer.  Shows what the
 * block and point caps do on a bus with more than a couple of slaves.
 */
#include <stdio.h>

#include "vg_discover.h"

#define DEV "/tmp/vgdisc-review/rs485"

int main(void)
{
  struct vg_discover_summary *sum = vg_discover_state();
  int i;
  int rc;

  vg_discover_reset(sum);
  rc = vg_bus_scan(sum, DEV, 9600, 1, 8, 50);
  printf("scan 1-8        -> rc=%d hits=%d\n", rc, sum->n_hits);
  for (i = 0; i < sum->n_hits; i++)
    {
      printf("   hit addr=%u\n", (unsigned)sum->hits[i].addr);
    }

  for (i = 0; i < sum->n_hits; i++)
    {
      if (!sum->hits[i].alive)
        {
          continue;
        }

      rc = vg_reg_probe_slave(sum, DEV, 9600, sum->hits[i].addr, 3, 32);
      printf("probe addr=%u   -> rc=%d blocks now=%d\n",
             (unsigned)sum->hits[i].addr, rc, sum->n_blocks);
    }

  printf("blocks collected = %d (cap %d)\n", sum->n_blocks,
         VG_DISCOVER_MAX_BLOCKS);
  printf("points inferred  = %d (cap %d)\n", vg_point_table_infer(sum),
         VG_DISCOVER_MAX_POINTS);
  for (i = 0; i < sum->n_points && i < 40; i++)
    {
      printf("   point %s addr=%u reg=%u\n", sum->points[i].id,
             (unsigned)sum->points[i].addr, (unsigned)sum->points[i].reg);
    }

  return 0;
}
